type TransportRequirements struct {
    RealTime        bool
    MultiClient     bool
    NetworkRequired bool
    Performance     string // &quot;high&quot;, &quot;medium&quot;, &quot;low&quot;
    Complexity      string // &quot;low&quot;, &quot;medium&quot;, &quot;high&quot;
