486.text:
Generating JSON schemas with WithInputSchema[T]() and WithOutputSchema[T]()
uses reflection at server start-up. In long-running servers this is a one-time
cost, but in serverless environments (AWS Lambda, Cloud Functions, Cloud Run
with scale-to-zero) the server is reconstructed on every cold start and the
reflection cost is paid again and again.
Use mcp.SchemaCache to pre-compute schemas at build time, persist them to
disk, and reload them at start-up:
// build/warm-cache.go — run as part of your build pipeline
func main() {
    cache := mcp.NewSchemaCache()
    if err := mcp.WarmFor[WeatherRequest](cache); err != nil {
        log.Fatal(err)
    }
    if err := mcp.WarmFor[WeatherResponse](cache); err != nil {
        log.Fatal(err)
    }
    if err := cache.Save(&quot;schemas.json&quot;); err != nil {
        log.Fatal(err)
    }
}
At runtime, load the cache once and pass it to the cache-aware tool options.
On a cache hit the schema is served straight from memory; on a miss the cache
falls back to reflection and stores the result for next time, so the same
code works locally without a pre-built cache file:
var cache = func() *mcp.SchemaCache {
    c, err := mcp.LoadSchemaCache(&quot;schemas.json&quot;)
    if err != nil {
        return mcp.NewSchemaCache() // fall back to live reflection
    }
    return c
}()

weatherTool := mcp.NewTool(&quot;get_weather&quot;,
    mcp.WithDescription(&quot;Get current weather&quot;),
    mcp.WithCachedInputSchema[WeatherRequest](cache),
    mcp.WithCachedOutputSchema[WeatherResponse](cache),
)
The cache key defaults to the package-qualified Go type name
(e.g. main.WeatherRequest). If you need a stable key that survives renames
or package moves, use the explicit-key variants:
if err := mcp.WarmFor[WeatherRequest](cache, &quot;weather.v1.input&quot;); err != nil {
    log.Fatal(err)
}

mcp.WithCachedInputSchemaKey[WeatherRequest](cache, &quot;weather.v1.input&quot;)
SchemaCache is safe for concurrent use, marshals to deterministic JSON
(sorted keys), and writes via an atomic temp-file-and-rename in Save.

487.text:
MCP-Go uses the google/jsonschema-go library with the jsonschema struct tag for schema generation:
type ExampleStruct struct {
    // Required field (no omitempty in json tag means required)
    Name string `json:&quot;name&quot; jsonschema:&quot;User&#x27;s full name&quot;`

    // Field with description
    Age int `json:&quot;age&quot; jsonschema:&quot;User age in years&quot;`

    // Optional field (omitempty makes it optional)
    PageSize int `json:&quot;pageSize,omitempty&quot; jsonschema:&quot;Number of items per page&quot;`

    // Optional field with description
    Status string `json:&quot;status,omitempty&quot; jsonschema:&quot;Current status&quot;`
}
:::info Migration Note
MCP-Go migrated from invopop/jsonschema to google/jsonschema-go. If you are upgrading from an older version, note these breaking changes:

Description tag: Changed from jsonschema_description:&quot;text&quot; to jsonschema:&quot;text&quot;
Required fields: The jsonschema:&quot;required&quot; tag is no longer supported. Fields without omitempty in their json tag are automatically required.
Validation constraints: Tags like jsonschema:&quot;enum=...&quot;, jsonschema:&quot;minimum=...&quot; are no longer supported in struct tags. Use mcp.WithRawInputSchema() for these constraints or define them with the builder API (mcp.WithString, mcp.WithNumber, etc.).
Additional properties: additionalProperties: false is now automatically included in generated schemas.
:::

488.text:
For more control over the response, use NewTypedToolHandler with manual result creation:
manualTool := mcp.NewTool(&quot;process_data&quot;,
    mcp.WithDescription(&quot;Process data with custom result&quot;),
    mcp.WithInputSchema[ProcessRequest](),
    mcp.WithOutputSchema[ProcessResponse](),
)

s.AddTool(manualTool, mcp.NewTypedToolHandler(manualProcessHandler))

func manualProcessHandler(ctx context.Context, req mcp.CallToolRequest, args ProcessRequest) (*mcp.CallToolResult, error) {
    // Process the data
    response := ProcessResponse{
        Status:      &quot;completed&quot;,
        ProcessedAt: time.Now(),
        ItemCount:   42,
    }

    // Create custom fallback text for backward compatibility
    fallbackText := fmt.Sprintf(&quot;Processed %d items successfully&quot;, response.ItemCount)

    // Return structured result with custom text
    return mcp.NewToolResultStructured(response, fallbackText), nil
}

489.text:
Here&#x27;s a complete example using the file operations pattern from earlier, enhanced with structured schemas:
// Define structured input for file operations
type FileOperationRequest struct {
    Path     string `json:&quot;path&quot; jsonschema:&quot;File path&quot;`
    Content  string `json:&quot;content,omitempty&quot; jsonschema:&quot;File content (for write operations)&quot;`
    Encoding string `json:&quot;encoding,omitempty&quot; jsonschema:&quot;File encoding&quot;`
}

// Define structured output
type FileOperationResponse struct {
    Success   bool      `json:&quot;success&quot; jsonschema:&quot;Operation success status&quot;`
    Path      string    `json:&quot;path&quot; jsonschema:&quot;File path&quot;`
    Message   string    `json:&quot;message&quot; jsonschema:&quot;Result message&quot;`
    Content   string    `json:&quot;content,omitempty&quot; jsonschema:&quot;File content (for read operations)&quot;`
    Size      int64     `json:&quot;size,omitempty&quot; jsonschema:&quot;File size in bytes&quot;`
    Modified  time.Time `json:&quot;modified,omitempty&quot; jsonschema:&quot;Last modified time&quot;`
}

func main() {
    s := server.NewMCPServer(&quot;File Manager&quot;, &quot;1.0.0&quot;,
        server.WithToolCapabilities(true),
    )

    // Create file tool with structured I/O
    createFileTool := mcp.NewTool(&quot;create_file&quot;,
        mcp.WithDescription(&quot;Create a new file with content&quot;),
        mcp.WithInputSchema[FileOperationRequest](),
        mcp.WithOutputSchema[FileOperationResponse](),
    )

    // Read file tool
    readFileTool := mcp.NewTool(&quot;read_file&quot;,
        mcp.WithDescription(&quot;Read file contents&quot;),
        mcp.WithInputSchema[struct {
            Path string `json:&quot;path&quot; jsonschema:&quot;File path to read&quot;`
        }](),
        mcp.WithOutputSchema[FileOperationResponse](),
    )

    s.AddTool(createFileTool, mcp.NewStructuredToolHandler(handleCreateFile))
    s.AddTool(readFileTool, mcp.NewStructuredToolHandler(handleReadFile))

    server.ServeStdio(s)
}

func handleCreateFile(ctx context.Context, req mcp.CallToolRequest, args FileOperationRequest) (FileOperationResponse, error) {
    // Validate path for security
    if strings.Contains(args.Path, &quot;..&quot;) {
        return FileOperationResponse{
            Success: false,
            Path:    args.Path,
            Message: &quot;Invalid path: directory traversal not allowed&quot;,
        }, nil
    }

    // Handle different encodings
    var data []byte
    switch args.Encoding {
    case &quot;base64&quot;:
        var err error
        data, err = base64.StdEncoding.DecodeString(args.Content)
        if err != nil {
            return FileOperationResponse{
                Success: false,
                Path:    args.Path,
                Message: fmt.Sprintf(&quot;Invalid base64 content: %v&quot;, err),
            }, nil
        }
    default:
        data = []byte(args.Content)
    }

    // Create file
    if err := os.WriteFile(args.Path, data, 0644); err != nil {
        return FileOperationResponse{
            Success: false,
            Path:    args.Path,
            Message: fmt.Sprintf(&quot;Failed to create file: %v&quot;, err),
        }, nil
    }

    // Get file info
    info, _ := os.Stat(args.Path)

    return FileOperationResponse{
        Success:  true,
        Path:     args.Path,
        Message:  &quot;File created successfully&quot;,
        Size:     info.Size(),
        Modified: info.ModTime(),
    }, nil
}

func handleReadFile(ctx context.Context, req mcp.CallToolRequest, args struct{ Path string }) (FileOperationResponse, error) {
    // Read file
    data, err := os.ReadFile(args.Path)
    if err != nil {
        return FileOperationResponse{
            Success: false,
            Path:    args.Path,
            Message: fmt.Sprintf(&quot;Failed to read file: %v&quot;, err),
        }, nil
    }

    // Get file info
    info, _ := os.Stat(args.Path)

    return FileOperationResponse{
        Success:  true,
        Path:     args.Path,
        Message:  &quot;File read successfully&quot;,
        Content:  string(data),
        Size:     info.Size(),
        Modified: info.ModTime(),
    }, nil
}

